        metrics = v.get('metrics', {})
        holdout = metrics.get('eval_ppl_holdout', metrics.get('holdout_ppl', 'N/A'))
        conclusion = v.get('conclusion', '')
        if conclusion in ['success', 'done']:
            print(f'{k}: holdout={holdout}, conclusion={conclusion}')

print('--- D&R ---')
for k, v in sorted(exps.items()):
    if ('dr_' in k.lower() or 'detect_remove' in k.lower() or 'detect_and_remove' in k.lower()) and 'seed' in k.lower():
        metrics = v.get('metrics', {})
        holdout = metrics.get('eval_ppl_holdout', metrics.get('holdout_ppl', 'N/A'))
        conclusion = v.get('conclusion', '')
        if conclusion in ['success', 'done']:
            print(f'{k}: holdout={holdout}, conclusion={conclusion}')

print('--- Permuted ---')
for k, v in sorted(exps.items()):
    if 'permut' in k.lower():
        metrics = v.get('metrics', {})
        holdout = metrics.get('eval_ppl_holdout', metrics.get('holdout_ppl', 'N/A'))
